// Fasst die Antwort von GET /kategorien zu EINEM Item zusammen.
let items = $input.all().map(i => i.json);
let liste = items;
if (items.length === 1) {
  const arr = Object.values(items[0]).find(v => Array.isArray(v));
  if (arr) liste = arr;
}
const kategorien = liste.map(k => {
  if (typeof k === 'string') return { name: k, beschreibung: '' };
  return { name: k.name ?? k.label ?? k.key ?? k.kategorie ?? String(k.id), beschreibung: k.beschreibung ?? k.description ?? '' };
});
const text = kategorien.map(k => k.beschreibung ? '- ' + k.name + ': ' + k.beschreibung : '- ' + k.name).join('\n');
return [{ json: { namen: kategorien.map(k => k.name), kategorien_text: text } }];

