// Prüft das LLM-Ergebnis. Unbekannte Hauptkategorie -> NICHT zurückschreiben.
// manuell_pruefen: nicht nach absoluter Konfidenz allein (LLM liefert fast immer >= 0,9),
// sondern auch nach Abstand zur Zweitkategorie und bei Sicherheitsbezug. Schwellen validiert (24 Testfaelle, 30.09.).
const MIN_KONFIDENZ = 0.6;
const MAX_ABSTAND = 0.3;       // Haupt und Zweit näher beieinander -> uneindeutig
const ZWEIT_RELEVANT = 0.3;    // wie ZWEITKATEGORIE_AB im Backend
const SICHERHEIT = 'Sicherheit und Gesundheit';

const namen = $('Kategorien bündeln').first().json.namen;
const r = $input.first().json.output ?? $input.first().json;
const klemme = x => (typeof x === 'number' ? Math.max(0, Math.min(1, x)) : undefined);

const gueltig = namen.includes(r.kategorie);
const konfidenz = klemme(r.konfidenz);

let zweitkategorie = r.zweitkategorie;
let zweitkonfidenz = klemme(r.zweitkonfidenz);
if (!namen.includes(zweitkategorie) || zweitkategorie === r.kategorie
    || zweitkategorie === 'Sonstiges' || zweitkonfidenz === undefined || konfidenz === undefined) {
  zweitkategorie = undefined; zweitkonfidenz = undefined;
} else if (zweitkonfidenz > konfidenz) {
  zweitkonfidenz = konfidenz;
}

const zweitRelevant = zweitkonfidenz !== undefined && zweitkonfidenz >= ZWEIT_RELEVANT;
const gruende = [];
if (konfidenz === undefined || konfidenz < MIN_KONFIDENZ) gruende.push('niedrige Konfidenz');
if (zweitRelevant && konfidenz - zweitkonfidenz < MAX_ABSTAND) gruende.push('Haupt und Zweit dicht beieinander');
if (zweitRelevant && zweitkategorie === SICHERHEIT) gruende.push('Sicherheitsbezug in Zweitkategorie');

return [{ json: {
  gueltig,
  geruecht_id: Number($('Webhook').first().json.body.geruecht_id),
  kategorie: r.kategorie,
  kernaussage: String(r.kernaussage ?? '').slice(0, 500),
  konfidenz,
  zweitkategorie,
  zweitkonfidenz,
  begruendung: String(r.begruendung ?? '').slice(0, 1000),
  manuell_pruefen: gruende.length > 0,
  pruefgruende: gruende.join(', '),
  fehler: gueltig ? '' : 'Unbekannte Kategorie "' + r.kategorie + '" – gültig: ' + namen.join(', ')
}}];
